mapper.select:
/*selectMasterCmCoBuyerCorpRegNoListPopList*/
SELECT (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS SITE_NAME , COM_NAME_LOC , CEO_NAME_LOC , IRS_NO , (SELECT DECODE(COUNT(X.CODE),0 ,'N','Y') FROM ( SELECT COD.CODE2 AS CODE FROM ICOMCOD3 COD WHERE COD.BUYER ='KRKORE0001' AND COD.TYPE = 'CDMP' AND COD.FLAG = 'Y' AND REPLACE(COD.CODE2,'-','') = REPLACE(CM.IRS_NO,'-','') AND COD.TEXT1 = #{st_dept_no} UNION ALL SELECT A.IRS_NO AS CODE FROM KEPCLOBA A WHERE REPLACE(A.IRS_NO,'-','') = REPLACE(CM.IRS_NO,'-','') AND A.DEPT_CD = #{st_dept_no} AND A.STATUS != 'D' ) X) AS CLBOA_YN FROM V_VOC_ICOMCMPY CM /* (ICOMCMPY - 회원사정보, MIS_BUYER_MNG - 고객사별 담당자 정보) */ WHERE 1=1 AND COM_CODE = #{st_buyer} AND SYS_TYPE = 'KA'
UNION ALL
SELECT COD1.TEXT1 AS SITE_NAME , IRS.IRS_NAME , IRS.CEO_NAME_LOC , IRS.IRS_NO , (SELECT DECODE(COUNT(X.CODE),0 ,'N','Y') FROM ( SELECT COD.CODE2 AS CODE FROM ICOMCOD3 COD WHERE COD.BUYER ='KRKORE0001' AND COD.TYPE = 'CDMP' AND COD.FLAG = 'Y' AND REPLACE(COD.CODE2,'-','') = REPLACE(IRS.IRS_NO,'-','') AND COD.TEXT1 = #{st_dept_no} UNION ALL SELECT A.IRS_NO AS CODE FROM KEPCLOBA A WHERE REPLACE(A.IRS_NO,'-','') = REPLACE(IRS.IRS_NO,'-','') AND A.DEPT_CD = #{st_dept_no} AND A.STATUS != 'D' ) X) AS CLBOA_YN FROM KEPTIRSN IRS /* 구매사 사업자정보 */ , ICOMCOD1 COD1 /* 마스터코드 관리 */ WHERE 1=1 AND IRS.SITE = COD1.CODE AND COD1.TYPE = 'VC04' AND COD1.CODE = 'KA' AND IRS.COM_CODE = #{st_buyer}
